WITH metrics AS (SELECT *, LAG(amount) OVER w_recent prev_amount, ROW_NUMBER() OVER w_recent row_seq FROM transactions WHERE is_flagged = TRUE WINDOW w_recent AS (PARTITION BY txn_type ORDER BY amount, id)) SELECT CASE WHEN amount >= 3700 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, CASE WHEN prev_amount >= 3200 THEN 'PREMIUM' ELSE 'STANDARD' END AS prev_amount_tier, DATE_TRUNC('WEEK', txn_time) AS week_start, COUNT_IF(txn_type = 'CREDIT') AS credit_events, APPROX_PERCENTILE(amount, 0.95) AS amount_p95, SUM(row_seq) AS total_row_seq FROM metrics GROUP BY CASE WHEN amount >= 3700 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN prev_amount >= 3200 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('WEEK', txn_time) HAVING COUNT_IF(txn_type = 'CREDIT') >= 1 ORDER BY amount_tier DESC
